def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    group = ""
    open_count = 0

    for char in paren_string:
        if char == "(":
            open_count += 1
        elif char == ")":
            open_count -= 1

        group += char

        if open_count == 0:
            result.append(group)
            group = ""

    return result

